mapper.select:
select *
from sys_user_third_party_bind
where is_deleted = 0
  and platform = #{platform}
  and app_id = #{appId}
  and third_party_user_id = #{thirdPartyUserId}
limit 1

mapper.update:
update sys_user_third_party_bind
set user_id = #{entity.userId},
    third_party_union_id = #{entity.thirdPartyUnionId},
    phone = #{entity.phone},
    last_login_time = #{entity.lastLoginTime},
    update_time = now(),
    update_user = #{entity.updateUser},
    update_user_name = #{entity.updateUserName}
where is_deleted = 0
  and platform = #{entity.platform}
  and app_id = #{entity.appId}
  and third_party_user_id = #{entity.thirdPartyUserId}

update sys_user_third_party_bind
set third_party_user_id = #{entity.thirdPartyUserId},
    third_party_union_id = #{entity.thirdPartyUnionId},
    phone = #{entity.phone},
    last_login_time = #{entity.lastLoginTime},
    update_time = now(),
    update_user = #{entity.updateUser},
    update_user_name = #{entity.updateUserName}
where is_deleted = 0
  and user_id = #{entity.userId}
  and platform = #{entity.platform}
  and app_id = #{entity.appId}
